NAME = 'GerOffBiSt: Offene Bibel - Studienfassung'
BOOK = 'I Corinthians'

CHAPTERS = {
    1: {
        1: 'Paulus, berufener Apostel Christi Jesu durch den Willen Gottes, und Sosthenes, der Bruder,',
        2: '{der} [an] die Gemeinde Gottes {seiend, sich befindend} in Korinth, (gottgeweihte =) heilige in Christus Jesus, berufene Heilige, mit allen, die anrufen den Namen unseres Herrn Jesus Christus an jedem Ort, dem ihrigen und dem unsrigen.',
        3: 'Gnade [sei] mit euch und Friede von Gott, unserem Vater, und [dem] Herrn Jesus Christus.',
        4: 'Ich danke meinem Gott jederzeit für euch wegen der Gnade Gottes, die euch gegeben wurde in Christus Jesus,',
        5: 'weil ihr in jeder Hinsicht reich gemacht wurdet in ihm, in jedem Wort (Lehre) und jeder Erkenntnis.',
        6: 'Da das Zeugnis von Christus befestigt (bestätigt) wurde in euch,',
        7: 'so dass ihr keinen Mangel leidet an keiner (lei) Gnadengabe (Geschenk, Gefälligkeit) (als) Erwartende die Offenbarung unseres Herrn Jesus Christus,',
        8: 'der auch festmachen wird euch bis zum Ende (Endpunkt, Ziel) unbescholten am Tag unseres Herrn Jesus Christus.',
        9: 'Treu [ist] Gott, durch den ihr Gerufene [seid] in die Gemeinschaft seines Sohnes Jesus Christus, unseres Herrn.',
        10: 'Ich bitte {aber} euch, Geschwister, durch (vermittelst, mit Hilfe von) den Namen unseres Herrn Jesus Christus, dass ihr alle dasselbe sagt und unter euch keine Spaltungen seien, seid aber Vollendete in derselben Gesinnung und in derselben Meinung (Entscheidung).',
        11: 'Denn mir ist zur Kenntnis gelangt über euch, meine Geschwister, über (die =) [Leute] von der Chloe, dass es Streitigkeiten bei euch gibt.',
        12: 'Ich (sage =) meine aber dies, dass jeder von euch sagt: Ich {zwar} bin ([Anhänger] des Paulus =) Pauliner - ich aber ([Anhänger] des Apollon =) Apolliner - ich aber ([Anhänger] des Kephas =) Kephanianer - ich dagegen [bin] ([Anhänger] des Christus =) Christ!',
        13: '[Ist] Christus [etwa] zerteilt? [Oder] ist [etwa] Paulus für euch gekreuzigt worden, oder seid ihr auf den Namen des Paulus Getaufte?',
        14: 'Ich danke Gott, dass ich niemanden von euch getauft habe außer Krispus und Gaius,',
        15: 'damit keiner sagen kann, {dass} er sei auf meinen Namen getauft worden.',
        16: 'Ich habe aber auch das Haus des Stephanas getauft, weiter weiß ich nicht, ob ich einen anderen getauft habe.',
        17: 'Nicht nämlich sandte mich Christus zu taufen, sondern zu predigen, nicht in Gewandtheit (Klugheit, Geschicklichkeit, Weisheit) des Wortes, damit nicht zunichte gemacht würde das Kreuz Christi.',
        18: 'Das Wort nämlich {das} vom Kreuz denen {zwar} verloren Gehenden ist es eine Dummheit, denen aber gerettet Werdenden, uns, ist es eine Kraft (Macht, Fähigkeit) Gottes.',
        19: 'Denn es steht geschrieben (Jesaja 29,14): Vernichten (verderben) werde ich die Klugheit (Weisheit) der Klugen (Weisen) und das Verständnis der Verständigen werde ich zunichte machen.',
        20: 'Wo [ist] ein Weiser? Wo ein Schriftgelehrter? Wo ein Disputierer dieser Welt? Hat Gott nicht als Torheit (Dummheit) erwiesen die Weisheit der Welt?',
        21: 'Weil denn in der Weisheit Gottes die Welt Gott nicht durch die Weisheit erkannte, hat es Gott gefallen, durch die Torheit (Dummheit) der Verkündigung die Glaubenden zu retten.',
        22: 'Denn {einerseits} die Juden fordern (begehren, verlangen, bitten) Zeichen, {andererseits} die Griechen suchen Weisheit,',
        23: 'wir aber verkündigen (predigen, lehren) Christus [als] Gekreuzigten, den Juden {zwar} [etwas] Anstößiges, den Heiden (Völkern) aber eine Torheit (Dummheit),',
        24: '{ihnen} aber den Berufenen, Juden und auch Griechen, Christus [als] Gottes Kraft (Macht) und Gottes Weisheit.',
        25: 'Denn das Törichte (Dumme) [an] Gott ist weiser als die Menschen, und das Schwache (Ohnmächtige) [an] Gott ist stärker als die Menschen.',
        26: 'Seht {nämlich, doch} eure Berufung an, Geschwister: {nämlich} Nicht viele Weise nach (dem Fleisch =) der menschlichen Natur, nicht viele Starke (Mächtige), nicht viele Vornehme.',
        27: 'Sondern das Törichte der Welt erwählte sich Gott, um die Weisen zu beschämen, und das Schwache der Welt erwählte sich Gott, um das Starke zu beschämen,',
        28: 'und (die niedere Abkunft =) das Unedle der Welt und das Verachtete erwählte sich Gott, das nicht Seiende, um das Seiende zu vernichten (beseitigen),',
        29: 'damit sich kein (Fleisch =) Wesen rühmen kann vor (angesichts von) Gott.',
        30: 'Aus ihm aber seid ihr in Christus, der für uns zur Weisheit wurde von Gott, [zur] Rechtfertigung, {und auch} Heiligung und Erlösung (Freilassung),',
        31: 'damit, wie geschrieben steht: „Der sich Rühmende soll sich im Herrn rühmen.“',
    },
    2: {
        1: 'Auch ich, kommend zu Euch, Geschwister [wörtl.: Brüder], bin nicht gekommen hervorragend in Rede oder Weisheit, verkündigend euch das Geheimnis Gottes.',
        2: 'Denn nicht habe ich gemeint etwas zu wissen bei euch außer Jesus Christus und diesen [als] Gekreuzigten.',
        3: 'Und ich in Schwachheit und Furcht und vielem Zittern zeigte ich mich bei euch,',
        4: 'und meine Rede und meine Verkündigung [zeigte sich] nicht in überredender, geschwätziger Weisheit, sondern im Beweis des Geistes und der Kraft,',
        5: 'damit euer Glaube nicht in menschlicher Weisheit [sei =] bestünde, sondern in der Kraft Gottes.',
        6: 'Weisheit aber reden wir zu den Vollkommenen (Vollendeten, Volljährigen, Eingeweihten), eine Weisheit aber nicht dieses Weltalters (Äons) noch der Herrscher dieses Weltalters (Äons), des vergänglichen;',
        7: 'sondern wir reden von Gottes Weisheit im Geheimnis, dem geheimgehaltenen, das vorherbestimmt hat Gott vor aller Weltzeit (Äonen) zu unserer Herrlichkeit,',
        8: 'das keiner der Herrscher dieses Weltalters (Äons) erkannt hat. Wenn nämlich sie es erkannt hätten, hätten sie nicht den Herrn der Herrlichkeit gekreuzigt.',
        9: 'Aber (sondern) wie geschrieben steht: was das Auge nicht sah und das Ohr nicht hörte und auf das Herz des Menschen nicht aufstieg, [das ist,] was bereitete Gott denen, die ihn lieben.',
        10: 'Uns aber offenbarte [es] Gott durch den Geist; denn der Geist erforscht (ergründet) alles, auch die Tiefe Gottes.',
        11: 'Wer denn kennt von den Menschen das [Wesen] des Menschen wenn nicht der Geist des Menschen, der in ihm ist? So auch das [Wesen] Gottes kennt keiner außer der Geist Gottes.',
        12: 'Wir aber haben nicht den Geist der Welt empfangen, sondern den Geist, der aus Gott [ist], damit wir wissen [das uns von Gott Geschenkte =] was uns von Gott geschenkt wurde.',
        13: 'Das reden wir auch, nicht in Worten, die von menschlicher Weisheit beigebracht (gelehrt) sind, sondern vom Geist beigebracht (gelehrt), als geistliche [Menschen] Geistliches deutend (auslegend).',
        14: 'Ein diesseitiger Mensch aber nimmt nicht das [Wesen?] des Geistes Gottes an; denn ihm [ist =] erscheint es als Torheit, und er kann nicht erkennen, weil [es] geistlich beurteilt wird.',
        15: 'Aber der geistliche [Mensch] beurteilt Alles, er selbst aber wird von niemandem beurteilt.',
        16: 'Denn „wer hat den Ratschluss des Herrn erkannt, der ihn belehre?“(Jesaja 40,13) Wir aber haben die Gesinnung (den Verstand, die Vernunft, die Meinung, den Ratschluss) Christi.',
    },
    3: {
        1: 'Ich aber, Brüder, vermochte (konnte) nicht mit euch zu reden wie zu Geistlichen, sondern wie zu Fleichschlichen, wie zu Kindern (Unreifen, Unmündigen) in Bezug auf Christus.',
        2: 'Milch ließ ich euch trinken, nicht [feste] Speise; denn ihr konntet [sie] noch nicht [essen, verdauen]. Aber nicht einmal jetzt könnt ihr,',
        3: 'noch nämlich seid ihr fleischlich (materialistisch). Da nämlich in euch Aggressivität (Streitlust) und Zorn (ist =) herrscht, seid ihr da nicht fleischlich (materialistisch) und lebt nach menschlicher Weise (Stil)?',
        4: 'Denn wenn einer sagt: Ich bin Pauliner, ein anderer aber: ich Apolliner, seid ihr dann nicht Menschen?',
        5: 'Was ist denn Apollos? Was aber ist Paulus? Diener (Helfer), durch die ihr gläubig geworden seid, und jeder [so], wie der Herr gab.',
        6: 'Ich habe angepflanzt, Apollos hat gegossen (bewässert), aber Gott hat wachsen lassen.',
        7: 'Sodass weder der etwas ist, der pflanzt, noch der, der begießt, sondern der, der wachsen lässt, Gott.',
        8: 'Wer anpflanzt (wörtl.: der Anpflanzende) aber und wer gießt (wörtl.: der Gießende) sind eins, jeder aber wird seinen eigenen Lohn empfangen gemäß der eigenen Arbeit (Mühe).',
        9: 'Gottes Mithelfer nämlich sind wir, Gottes Ackerfeld, Gottes Bau (Gebäude) seid ihr.',
        10: 'Nach der Gnade Gottes, die mir gegeben (geschenkt) wurde, habe ich wie ein weiser (sachverständiger) Baumeister den Grundstein (das Fundament) gelegt, ein anderer aber baut darauf auf. Jeder aber sehe, wie er darauf aufbaut.',
        11: 'Denn einen anderen Grundstein (ein anderes Fundament) kann niemand legen als das (Liegende =), das gelegt ist, das ist Jesus Christus.',
        12: 'Wenn aber jemand auf den Grundstein (das Fundament) Gold, Silber, Edelstein, Holz, Gras (Heu), Stroh aufbaut,',
        13: 'wird das Werk eines jeden offenbar (sichtbar, kenntlich, bekannt) werden, denn der Tag wird es offenbar machen (kundtun), denn (weil) im Feuer wird es offenbart (aufgedeckt, ans Licht gebracht). Und wie das Werk eines jeden beschaffen ist, wird das Feuer prüfen.',
        14: 'Wenn jemandes Werk bleiben wird, das er aufgebaut hat, wird er Lohn empfangen.',
        15: 'Wenn jemandes Werk verbrennen wird, wird er Schaden leiden (bestraft werden), er selbst aber wird gerettet werden, aber so (derartig) wie durch Feuer.',
        16: 'Wisst ihr nicht, dass ihr ein Tempel Gottes seid und der Geist Gottes in euch wohnt?',
        17: 'Wenn jemand den Tempel Gottes vernichtet (zerstört, verdirbt, zugrunde richtet), wird Gott diesen vernichten (zerstören, verderben, zugrunde richten); denn der Tempel des Herrn ist heilig - das seid ihr!',
        18: 'Keiner soll sich selbst betrügen: wenn jemand als Weise gilt bei euch in dieser Weltzeit (Äon), soll er ein Narr werden, damit er weise wird (um weise zu werden).',
        19: 'Denn die Weisheit dieser Welt ist Torheit bei Gott. Denn es steht geschrieben (Hiob 5,12f): „Der die Weisen fängt in ihrer Verschlagenheit“,',
        20: 'und wiederum (Psalm 93,11): „Der Herr (er) kennt die Gedanken der Weisen, dass sie nichtig (eitel) sind“.',
        21: 'So soll sich keiner rühmen bei den Menschen. Denn alles ist euer,',
        22: 'ob Paulus, Apollos, Kephas, die Welt, das Leben, der Tod, Gegenwärtiges oder Zukünftiges: alles ist euer,',
        23: 'ihr aber seid Christi, Christus aber ist Gottes.',
    },
    4: {
        1: 'So soll man (wörtl.: Mensch) uns ansehen (bewerten) als Diener (Gehilfen) Christi und Verwalter der Geheimnisse (Mysterien) Gottes.',
        2: 'Hierbei weiterhin (also) verlangt (fordert) man von den Verwaltern, dass einer treu (zuverlässig) sich zeigt (erscheint, sich erweist, erfunden wird).',
        3: 'Mir aber ist es völlig gleichgültig, ob ich von euch beurteilt werde oder von einem menschlichen [Gerichts-] Tag. Und nicht nur das, sondern ich beurteile auch mich selbst nicht.',
        4: 'Denn ich bin mir nichts bewusst, aber dadurch (damit) bin ich nicht gerechtfertigt; der mich aber beurteilt, ist der Herr.',
        5: 'Deshalb (daher) richtet (nicht etwas =) nichts vor der Zeit bis der Herr kommen wird, der auch ans Licht bringen (aufdecken) wird das im Finsteren Verborgene und offenbaren wird die Absichten der Herzen. Und dann wird Anerkennung (Lob) werden jedem von Gott.',
        6: 'Dies aber, Brüder, bringe ich zur Darstellung (exemplifiziere) an mir und Apollon um euretwillen, damit ihr an uns lernt das „Nicht über [das hinaus], was geschrieben steht“, damit ihr euch nicht einer für den einen aufbläht gegen den anderen.',
        7: 'Denn wer räumt dir einen Vorrang ein? Was aber hast (besitzt) du, was du nicht [als Geschenk] empfingst? Wenn du es aber auch [als Geschenk] empfangen hast, was rühmst du dich, als hättest du es nicht [als Geschenk] empfangen?',
        8: 'Schon seid ihr satt!Schon seid ihr reich! Ohne uns kamt ihr zur Herrschaft! Und wenn ihr doch wenigstens zur Herrschaft gekommen wäret, damit auch wir an eurer Herrschaft teilnähmen!',
        9: 'Ich meine (glaube) nämlich, Gott hat uns, die Apostel, als geringste (unterste) hingestellt, wie dem Tode Verfallene, weil wir ein Schauspiel geworden sind der Welt und Engeln und Menschen.',
        10: 'Wir [sind] töricht um Christi willen, ihr [seid] klug (verständig) in Christus; wir [sind] schwach, ihr [seid] stark; ihr [seid] vornehm (berühmt), wir [sind] ungeehrt (unansehnlich).',
        11: 'Bis zur jetzigen Stunde hungern wir, {und} dürsten wir, {und} sind wir schlecht gekleidet, {und} werden geohrfeigt, {und} sind unstet',
        12: 'und mühen (plagen) uns, Arbeitende mit den eigenen Händen. Geschmäht werdend segnen wir, verfolgt werdend dulden wir,',
        13: 'verlästert werdend trösten wir. Wir sind gleichsam zum Abschaum (zu Sündenböcken) der Welt geworden, der Unrat (Schmutz, Abschaum) aller bis heute.',
        14: 'Nicht euch beschämend schreibe ich das, sondern wie meine geliebten Kinder euch zurechtweisend (weise ich euch zurecht).',
        15: 'Wenn ihr nämlich [auch] unzählige Pädagogen (Knabenführer, Hofmeister) in Christus habt, [habt] ihr aber nicht viele Väter: denn in Christus Jesus durch das Evangelium habe ich euch gezeugt!',
        16: 'Ich bitte euch nun: werdet meine Nachahmer!',
        17: 'Deshalb habe ich euch Timotheus geschickt, der ist mein geliebtes Kind und treu im Herrn, der wird euch erinnern an meine Wege (Wandel, Handlungsweise) in Christus Jesus, wie ich überall in jeder Gemeinde lehre.',
        18: 'Dass ich aber nicht zu euch kommen würde, haben sich einige aufgeblasen (gebrüstet);',
        19: 'ich werde aber bald (schnell, eilig, sofort) zu euch kommen, wenn der Herr will, und ich will erkunden nicht nur das Wort der Aufgeblasenen, sondern auch die Kraft (Vollmacht).',
        20: 'Denn das Reich Gottes [besteht] nicht im Wort, sondern in der Kraft (Vollmacht).',
        21: 'Was wollt ihr? Soll ich mit der Rute zu euch kommen, oder in der Liebe und mit dem Geist der Sanftmut?',
    },
    6: {
        4: 'Wenn ihr nun Fälle des alltäglichen Lebens zu entscheiden habt, dann setzt die Übergangenen in der Gemeinde ein, diese und nicht die Ungläubigen!',
    },
    7: {
        1: 'Zu dem, was ihr schriebt, es ist gut für einen Mann, eine Frau nicht zu berühren',
        2: 'Um der Unzucht willen soll jeder [Mann] seine eigene Frau haben und jede [Frau] ihren eigenen Mann.',
        3: 'Der Mann soll seine Pflicht der Frau gegenüber erfüllen, ebenso (in gleicher Weise) die Frau dem Mann gegenüber.',
        4: 'Die Frau verfügt nicht (hat keine Verfügungsgewalt) über ihren {eigenen} Körper, sondern der Mann, ebenso (in gleicher Weise) verfügt der Mann nicht (hat keine Verfügungsgewalt) über seinen {eigenen} Körper, sondern die Frau.',
        5: 'Entzieht euch nicht einander, außer in gegenseitigem Einvernehmen (nach Übereinkunft) für einen begrenzten Zeitraum (für den gegenwärtigen Augenblick), um euch dem Gebet zu widmen und dann wieder zusammen zu sein, damit euch der Satan nicht versucht durch eure Geilheit (Zügellosigkeit).',
        6: 'Dies aber sage ich als Zugeständnis, nicht als Befehl.',
        7: 'Ich wollte {aber}, dass alle Menschen (Männer?) wie ich wären; aber jeder hat seine eigene Gabe von Gott, der eine so, der andere so.',
        8: 'Den Unverheirateten und den Witwen sage ich, dass es gut wäre, wenn sie blieben wie ich.',
        9: 'Wenn sie aber nicht enthaltsam sein können, sollen sie heiraten, denn es ist besser, zu heiraten als zu brennen.',
        10: 'Den Verheirateten aber befehle {ich,} nicht ich, sondern der Herr, dass eine Frau sich vom Mann nicht scheiden soll',
        11: '- falls sie aber geschieden ist, soll sie unverheiratet bleiben oder sich mit dem Mann aussöhnen -, und der Mann soll die Frau nicht verstoßen',
        12: 'Den übrigen aber sage ich, nicht der Herr: Wenn ein Bruder eine nichtgläubige Frau hat, und (diese) sie willigt ein, mit ihm (ehelich) zusammenzuleben, soll er sie nicht verstoßen.',
        13: 'Und die Frau, wenn sie einen nichtgläubigen Mann hat, und (dieser) er willigt ein, mit ihr (ehelich) zusammenzuleben, soll sie ihn nicht verstoßen.',
        14: 'Denn der nichtgläubige Mann wird durch die Frau geheiligt, und die nichtgläubige Frau durch den Bruder; denn sonst sind demnach ihre Kinder unrein, jetzt aber sind sie heilig.',
        15: 'Wenn aber der Nichtgläubige sich scheiden will, soll er sich scheiden. Der Bruder oder die Schwester ist in diesem Fall nicht [dem Eheversprechen] unterworfen. Gott hat euch zum (im) Frieden berufen.',
        16: 'Denn {was} weißt du, Frau, ob du den Mann retten wirst? Oder {was} weißt du, Mann, ob du die Frau retten wirst?',
        17: 'Doch (Sondern) jeder soll so leben (wandeln), wie der Herr es ihm zugeteilt, jeder, wie der Herr ihn berufen hat. {Und} so ordne ich es in allen Gemeinden an.',
        18: 'Wer als Beschnittener berufen wurde, soll nicht die Vorhaut überziehen; wer als Unbeschnittener berufen wurde, soll sich nicht beschneiden lassen.',
        19: 'Die Beschneidung ist nichts und die Unbeschnittenheit ist nichts, sondern die Beachtung der Gebote Gottes.',
        20: 'Jeder soll in der Berufung (dem Beruf) bleiben, in der er berufen wurde (in dem ihn der Ruf Gottes traf).',
        21: 'Du wurdest als Sklave berufen; das soll dich nicht kümmern. Aber wenn du auch Freiheit erlangen kannst, gebrauche sie (die Sklaverei? die Freiheit?) um so mehr.',
        22: 'Denn der Sklave, der durch den (im) Herrn berufen wurde, ist ein Freigelassener des Herrn, wie (in gleicher Weise) der Freie, der berufen wurde, ein Sklave Christi ist.',
        23: 'Ihr seid bar bezahlt worden (wurdet gegen Barzahlung erworben); werdet nicht Sklaven von Menschen.',
        24: 'Jeder soll darin bleiben, Brüder, worin er von Gott berufen wurde.',
        25: 'Über die Jungfrauen {aber} besitze ich kein Gebot des Herrn. Ich bin aber der Meinung, dass ich ein Vertrauensmann bin, weil ich vom Herrn begnadigt wurde (Erbarmen fand).',
        26: 'Ich meine nun, dies sei gut (dass dies gut sei) wegen der bevorstehenden Not, dass es für den Menschen gut ist, wenn er bleibt, wie er ist.',
        27: 'Wurde dir eine Frau gegeben, suche nicht die Scheidung (Trennung); hast du dich von einer Frau getrennt (frei gemacht), suche keine Frau.',
        28: 'Wenn du aber heiratest, sündigst du nicht, und wenn die Jungfrau heiratet, sündigt sie nicht. Leibliche Bedrängnis werden diese aber (haben =) erleben, ich aber schone euch (= würde euch gern schonen?).',
        29: 'Dies aber sage ich, Brüder, die Zeit ist zusammengedrängt (beschränkt). Hinfort (zukünftig) sollen die Frauen haben sein, als hätten sie keine,',
        30: 'und die weinen, als weinten sie nicht, und die sich freuen, als freuten sie sich nicht, und die kaufen, als besäßen sie nicht,',
        31: 'und die die Welt gebrauchen, als missbrauchten sie sie nicht, denn diese Welt selbst (die Gestalt, das Wesen dieser Welt) vergeht.',
        32: 'Ich möchte aber, dass ihr sorglos (sorgenfrei) seid. Der Unverheiratete sorgt für (trägt Sorge für) die Angelegenheiten des Herrn, wie er dem Herrn gefallen (zu Gefallen sein) kann.',
        33: 'Der Verheiratete aber sorgt sich um (trägt Sorge um) die Welt, wie er der Frau gefallen (zu Gefallen sein) kann,',
        34: 'und ist in sich gespalten. Und die Frau, die Unverheiratete und die Jungfrau, sorgt für (trägt Sorge für) die Angelegenheiten des Herrn, damit sie heilig ist sowohl körperlich als auch geistig (geistlich). Aber die Verheiratete sorgt sich um (trägt Sorge um) die Welt, wie sie dem Mann gefallen (zu Gefallen sein) kann.',
        35: 'Dies aber sage ich zu eurem eigenen Vorteil (Nutzen), nicht, um euch eine Schlinge überzuwerfen, sondern damit ihr ungestört (nicht abgelenkt) anständig und beharrlich im Herrn [seid].',
        36: 'Wenn aber einer glaubt, sich unanständig gegenüber seiner Jungfrau zu benehmen (sich seiner Jungfrau gegenüber schämen zu müssen), wenn er überreif ist und so geschehen muss, was er tun will, sündigt er nicht; sie sollen heiraten.',
        37: 'Wer aber in seinem Herz fest steht, ohne Zwang, aber Macht hat über seinen Willen und dies in seinem Herzen beschließt, seine Jungfrau zu bewahren (= unberührt zu lassen), tut recht [daran].',
        38: 'So tut auch recht, wer seine Jungfrau heiratet, aber wer nicht heiratet, tut Besseres.',
        39: 'Eine Frau ist (gegeben =) gebunden, solange ihr Mann lebt; wenn aber der Mann entschlafen ist, ist sie frei, zu heiraten, wen sie will, allein [dass es] im Herrn [geschieht].',
        40: 'Glücklicher (seliger) aber ist sie, wenn sie so bleibt, meiner Meinung nach. Ich meine aber, dass auch ich den Geist Gottes habe.',
    },
    9: {
        19: 'Denn weil (obwohl) ich frei bin allen gegenüber, habe ich mich allen zum Sklaven gemacht, damit ich möglichst viele gewinne.',
        20: '[Das heißt:] für die Juden bin ich wie ein Jude geworden, damit ich [die] Juden gewinne; für die unter dem Gesetz [des Mose] bin ich wie einer unter dem Gesetz geworden – auch wenn ich selbst nicht unter dem Gesetz bin – damit ich die unter dem Gesetz gewinne;',
        21: 'für die ohne Gesetz wie einer ohne Gesetz – auch wenn ich nicht ohne Gesetz Gottes bin, sondern [ich bin] im Gesetz Christi – damit ich die ohne Gesetz gewinne;',
        22: 'für die Schwachen bin ich schwach geworden, damit ich die Schwachen gewinne; für alle [diese] bin ich alles geworden, damit ich von allen welche errette.',
        23: 'Alle diese Dinge tue ich um des Evangeliums willen, damit auch ich Anteil am Evangelium habe.',
        24: 'Wisst ihr [denn] nicht, dass zwar alle Athleten am Wettkampf teilnehmen, aber nur einer den Siegeskranz bekommt?',
        25: 'Jeder aber, der kämpft, übt sich in Verzicht (Selbstbeherrschung) in allen [Lebensbereichen]. Die Athleten tun es, damit sie einen Siegeskranz bekommen, der doch vergänglich ist; wir aber für einen unvergänglichen.',
        26: '[Das gilt] auch für mich: Ich laufe nicht wie einer, der ziellos umherirrt, ich boxe nicht wie einer, der wild um sich haut;',
        27: 'sondern ich führe einen harten Kampf gegen mich selbst und zwinge meinen Körper, mir zu gehorchen, damit ich nicht an dem, was ich anderen gepredigt habe, selbst untauglich werde (scheitere).',
    },
    10: {
        1: 'Ich will nämlich nicht, dass ihr nicht wisst (versteht), dass eure Väter alle unter der Wolke waren und alle durch das Meer zogen',
        2: 'und alle auf (in) {den} Moses (hinein) getauft wurden in der Wolke und in dem Meer',
        3: 'und alle dieselbe geistliche Nahrung aßen',
        4: 'und alle denselben geistlichen Trank tranken: Sie tranken nämlich aus einem geistlichen Felsen, der nachfolgte, der Fels aber war {der} Christus.',
        5: 'Aber Gott fand nicht an (in) den meisten von ihnen Wohlgefallen, denn sie wurden in der Wüste getötet (niedergestreckt).',
        13: '... treu aber [ist] Gott, welcher nicht zulassen wird, dass ihr über das Vermögen (Können) versucht werdet, sondern mit der Versuchung macht er auch den Ausgang, dass ihr [es] ertragen könnt.',
        31: 'Ob ihr nun esst oder trinkt oder irgendetwas tut (macht), alles tut (macht) zur Ehre (Herrlichkeit) Gottes.',
    },
    11: {
        23: 'Ich nämlich nahm in Empfang von dem Herrn, was ich auch euch übergeben (weitergeben) habe, dass der Herr Jesus in der Nacht, in der er übergeben (ausgeliefert) wurde, [das] Brot (in die Hand) nahm (ergriff),',
        24: '{und} dankte (Dank sagte) und [es (das Brot)] brach und sprach: Dies ist mein Leib (Körper), der für (zum Vorteil von) euch [ist], dies tut zur Erinnerung an mich.',
        25: 'In gleicher Weise (ebenso) auch das Becherchen (Kelchlein, Trinkgefäßchen) nach dem Essen (Speisen) und sagte: Dieses Becherchen ist das neue Testament (Vertrag, Bund) in meinem Blut. Dies tut so oft ihr trinkt zur Erinnerung an mich.',
    },
    12: {
        1: 'Über die der Geistgaben, Brüder, will ich euch nicht im Unwissen lassen.',
        2: 'Ihr wisst, dass, als ihr Heiden wart, ihr schon zu den stummen Götzenbildern weggeführt wurdet, dass ihr schon geführt wurdet.',
        3: 'Deshalb offenbare ich euch, dass niemand im Geist Gottes schwätzend sagt: „Verflucht [sei] Jesus“, und keiner ist fähig zu sagen: „Herr ist Jesus“, wenn nicht im Heiligen Geist.',
        4: 'Es gibt Zuteilungen aber der Gnadengaben, der Geist aber ist derselbe;',
        5: 'Und es gibt Unterscheidungen der Diakonie, und der Herr ist derselbe;',
        6: 'Und es gibt Unterscheidungen in der Wirkung, der Gott aber ist derselbe, der wirkt alles in allen.',
        7: 'Jedem ist es gegeben, die Offenbarung des Geistes zusammenzutragen.',
        8: 'Denn nämlich dem einen ist durch den Geist gegeben das Wort der Weisheit, dem anderen aber das Wort der Erkenntnis gemäß demselben Geist,',
        9: 'Dem einen der Glaube in demselben Geist, dem anderen aber die Gabe der Heilung in dem einen Geist,',
        10: 'Dem anderen aber die Wirkungen der Kräfte, dem anderen aber die Prophetie, dem anderen aber die Unterscheidung der Geister, einem anderen die Sprache der Zungen, einem anderen aber die Auslegung der Zungen;',
        11: 'Alles aber wirkt der eine Geist, der zuteilt einem jeden Einzelnen, genau wie er will.',
    },
    13: {
        1: 'Wenn ich (einer) in den Sprachen der Menschen spräche (spreche) oder (und [selbst]) [in der] der Engel, aber keine Liebe hätte (habe, nicht liebte), dann wäre (bin) ich (er) ein schallender Gong (Kupfer) oder eine klingende (lärmende) Zimbel {geworden}.',
        2: 'Und wenn ich (einer) Prophetie hätte (habe, prophezeite) und alle Geheimnisse und jede Erkenntnis (Wissen) wüsste (weiß), und wenn ich (einer) allen (genügend) Glauben hätte (habe, glaubte), um Berge zu versetzen, aber keine Liebe hätte (habe, liebte), dann wäre (bin) ich (er) nichts.',
        3: 'Und wenn ich (einer) all meine (seine) Besitztümer austeilen würde (austeilt) und wenn ich (er) meinen (seinen) Körper ausliefern würde (ausliefert), damit ich verbrannt (so dass ich gerühmt) würde, aber keine Liebe hätte (habe, liebte), dann würde es mir (ihm) nichts nützen (nützt es mir nichts).',
        4: 'Die Liebe ist sanftmütig (langmütig), mild (freundlich) {ist die Liebe}; die Liebe ist nicht aggressiv (ereifert sich nicht?), sie ist nicht prahlsüchtig, sie ist nicht hochmütig (arrogant),',
        5: 'sie ist nicht unsittlich (schamlos), sie strebt nicht nach dem Ihrigen, sie ist nicht [leicht] reizbar, sie rechnet das Schlechte (Böse) nicht an.',
        6: 'Sie freut sich nicht über die Ungerechtigkeit, sondern sie freut sich über die Wahrheit;',
        7: 'sie bedeckt (vergibt, erträgt) alles, sie glaubt alles, sie hofft alles, sie erduldet alles.',
        8: 'Die Liebe kommt niemals zu Fall. Ob es dagegen Prophetien [seien] - sie werden vergehen; ob es Sprachen [seien] - sie werden aufhören; ob es Erkenntnis (Wissen) [sei] - sie wird vergehen.',
        9: 'Denn [nur] bruchstückhaft erkennen wir (haben wir Einsicht) und bruchstückhaft prophezeien wir,',
        10: 'aber sobald das Vollkommene (Vollständige) kommt, wird das Bruchstückhafte vergehen.',
        11: 'Als ich ein Kind war, redete ich wie ein Kind, dachte ich wie ein Kind, urteilte (argumentierte) ich wie ein Kind; seit ich ein Mann geworden bin (nun, da ich ein Mann bin), habe ich die [Dinge] des Kindes vergehen lassen.',
        12: 'Denn wir sehen jetzt in einem Rätsel (indirekt, undeutlich) durch einen (in einem) Spiegel, dann aber (und erst dann) von Angesicht zu Angesicht; jetzt erkenne ich bruchstückhaft, dann aber (und erst dann) werde ich [so] erkennen, wie auch ich erkannt worden bin.',
        13: 'Jetzt aber bleiben Glaube, Hoffnung, Liebe – diese drei; und (aber) die Größte von ihnen [ist] die Liebe.',
    },
    15: {
        1: 'Ich lasse euch aber, [Schwestern und] Brüder, die Frohbotschaft (die gute Nachricht, das Evangelium) wissen (mache kund, offenbare), die ich euch predigte, die ihr auch annahmt, in der ihr auch fest steht,',
        2: 'durch die ihr auch gerettet werdet, in welchem Wortlaut ich sie euch predigte, wenn ihr sie festhaltet, es sei denn, ihr glaubtet ohne Sinn und Verstand (ihr wäret umsonst gläubig geworden).',
        3: 'Denn ich habe euch in erster Linie (unter den wichtigsten Stücken) überliefert, was ich ich angenommen habe: „Dass Christus für unsere Sünden starb gemäß der Schrift,',
        4: '{und} dass er begraben wurde, {und} dass er am dritten Tag auferweckt wurde gemäß der Schrift,',
        5: 'und dass er Kephas erschien (sich zeigte), darauf den Zwölfen“.',
        6: 'Darauf erschien er mehr als 500 [Schwestern und] Brüdern auf einmal, von denen die meisten (bis jetzt bleiben =) noch leben, einige aber sind entschlafen.',
        7: 'Darauf erschien er Jakobus, dann allen Aposteln.',
        8: 'Als letztem von allen aber, quasi wie (gleichsam als) einer Fehlgeburt, erschien er auch mir.',
        9: 'Ich bin ja (nämlich) der geringste der Apostel, {der ich} nicht einmal geeignet {bin}, Apostel genannt zu werden, weil ich die Gemeinde Gottes verfolgte.',
        10: 'Gott sei Dank (durch Gottes Gnade) aber bin ich, was ich bin, und seine Gnadengabe für mich (geschah =) blieb nicht ohne Erfolg, sondern mehr als alle anderen plagte ich mich (arbeitete ich mich ab), aber nicht ich, sondern Gottes Gnabengabe, die mit mir ist.',
        11: 'Ob nun ich oder {ob} jene, so predigen wir, und so habt ihr geglaubt.',
        12: 'Wenn aber Christus verkündigt wird, dass er aus den Toten auferstanden (auferweckt) ist, wie sagen einige bei euch: Es gibt keine Auferstehung der Toten (Totenauferweckung)?',
        13: 'Wenn es aber keine Auferstehung der Toten (Totenauferweckung) gibt, ist auch Christus nicht auferstanden (auferweckt).',
        14: 'Wenn aber Christus nicht auferstanden (auferweckt) ist, ist folglich auch unsere Verkündigung (leer =) inhaltsleer (hohl), leer auch euer Glaube.',
        15: '(Wir werden aber auch gefunden =) Wir stehen aber auch da als falsche Zeugen Gottes, denn wir haben Zeugnis (gegen =) im Widerspruch zu Gott abgelegt, dass er Christus auferweckt habe, den er nicht auferweckte, wenn (anders=), wie sie sagen, die Toten nicht auferstehen (auferweckt werden).',
        16: 'Denn wenn die Toten nicht auferstehen (auferweckt werden), dann ist auch Christus nicht auferstanden (auferweckt worden).',
        17: 'Wenn aber Christus nicht auferstand (auferweckt wurde), ist euer Glaube nichtig (eitel), dann seid ihr noch in euren Sünden,',
        18: 'folglich sind auch die in Christus Entschlafenen (verloren =) der Macht des Todes verfallen.',
        19: 'Wenn wir allein in diesem Leben auf Christus hoffen, sind wir bemitleidenswerter als alle anderen Menschen.',
        20: 'Nun (jetzt) aber ist Christus auferstanden (auferweckt worden) von den Toten als Erster (Erstling) der Entschlafenen.',
    },
}
